import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';

Object.assign(process.env, { ENV_FILE: '/nonexistent', IG_USER_ID: '1', IG_ACCESS_TOKEN: 't' });
const { validateFields, UploadError } = await import('../server/uploads.js');

const codeOf = (fields) => {
  try {
    validateFields(fields);
    return null;
  } catch (e) {
    assert.ok(e instanceof UploadError, `expected an UploadError, got ${e}`);
    return e.code;
  }
};

test('one-character club names are rejected as too_short', () => {
  assert.equal(codeOf({ clubName: 'x' }), 'too_short');
  assert.equal(codeOf({ clubName: '  x  ' }), 'too_short', 'counted after trimming');
  assert.equal(codeOf({ clubName: 'x\u200B' }), 'too_short', 'zero-width characters do not count');
  assert.equal(codeOf({ clubName: '\u0000\u015E\n' }), 'too_short', 'control characters do not count');
});

test('two characters are enough and the max still applies', () => {
  assert.equal(validateFields({ clubName: 'IT' }).clubName, 'IT');
  assert.equal(validateFields({ clubName: ' \u015E\u00FC ' }).clubName, '\u015E\u00FC');
  assert.equal(validateFields({ clubName: 'x'.repeat(100) }).clubName.length, 100);
  assert.equal(codeOf({ clubName: 'x'.repeat(101) }), 'too_long');
});

test('empty names are still missing_name and other checks still run', () => {
  assert.equal(codeOf({ clubName: '' }), 'missing_name');
  assert.equal(codeOf({ clubName: '   ' }), 'missing_name');
  assert.equal(codeOf({}), 'missing_name');
  assert.equal(codeOf({ clubName: 'Okan', about: 'y'.repeat(3001) }), 'too_long');
  assert.equal(codeOf({ clubName: 'Okan', instagram: 'not a username!' }), 'bad_instagram');
});

test('the form has a message for too_short', () => {
  const app = fs.readFileSync(new URL('../public/app.js', import.meta.url), 'utf8');
  assert.match(app, /too_short['"]?\s*:\s*['"`][^'"`]+['"`]/);
});

