import test from 'node:test';
import assert from 'node:assert/strict';

Object.assign(process.env, { ENV_FILE: '/nonexistent', IG_USER_ID: '1', IG_ACCESS_TOKEN: 't' });
const { parseInstagram, validateFields, UploadError } = await import('../server/uploads.js');

test('instagr.am short links give the username', () => {
  assert.equal(parseInstagram('instagr.am/Okan.Kulup'), 'okan.kulup');
  assert.equal(parseInstagram('https://instagr.am/kulup/'), 'kulup');
  assert.equal(parseInstagram('http://instagr.am/kulup?igsh=abc123'), 'kulup');
  assert.equal(parseInstagram('  HTTPS://INSTAGR.AM/Kulup_1/#top '), 'kulup_1');
  assert.equal(validateFields({ clubName: 'Okan', instagram: 'https://instagr.am/okan_sinema/' }).instagram, 'okan_sinema');
});

test('instagr.am links to posts and reels are not usernames', () => {
  assert.equal(parseInstagram('instagr.am/p/Cabc123'), null);
  assert.equal(parseInstagram('https://instagr.am/reel/Cabc123/'), null);
  assert.throws(() => validateFields({ clubName: 'Okan', instagram: 'instagr.am/p/Cabc123' }), (e) => e instanceof UploadError && e.code === 'bad_instagram');
});

test('existing forms are unchanged', () => {
  assert.equal(parseInstagram('@okan_sinema'), 'okan_sinema');
  assert.equal(parseInstagram('Kulup'), 'kulup');
  assert.equal(parseInstagram('https://www.instagram.com/kulup/?hl=tr'), 'kulup');
  assert.equal(parseInstagram('instagram.com/p/Cabc123'), null);
  assert.equal(parseInstagram('not a username!'), null);
  assert.equal(parseInstagram(''), '');
  assert.equal(parseInstagram(undefined), '');
});

