import test from 'node:test';
import assert from 'node:assert/strict';
import { RateLimiter } from '../server/ratelimit.js';

const realNow = Date.now;
let now = 1_000_000;
Date.now = () => now;
test.after(() => { Date.now = realNow; });

test('rejected hits are not recorded, so a blocked client gets back in when the window passes', () => {
  now = 1_000_000;
  const rl = new RateLimiter(2, 1000);
  assert.equal(rl.hit('ip'), false);
  now += 100;
  assert.equal(rl.hit('ip'), false);
  for (let i = 0; i < 50; i++) {
    now += 10;
    assert.equal(rl.hit('ip'), true);
  }
  assert.equal(rl.isBlocked('ip'), true);
  assert.equal(rl.isBlocked('other'), false);
  now = 1_001_001; // the first accepted hit has left the window, the second has not
  assert.equal(rl.isBlocked('ip'), false);
  assert.equal(rl.hit('ip'), false);
  assert.equal(rl.hit('ip'), true);
});

test('a limit of 0 still disables the limiter', () => {
  now = 2_000_000;
  const off = new RateLimiter(0, 1000);
  for (let i = 0; i < 20; i++) assert.equal(off.hit('ip'), false);
  assert.equal(off.isBlocked('ip'), false);
});

test('undo still gives a reserved slot back', () => {
  now = 3_000_000;
  const rl = new RateLimiter(1, 1000);
  assert.equal(rl.isBlocked('ip'), false);
  assert.equal(rl.hit('ip'), false);
  assert.equal(rl.isBlocked('ip'), true);
  rl.undo('ip');
  assert.equal(rl.isBlocked('ip'), false);
  assert.equal(rl.hit('ip'), false);
  assert.equal(rl.hit('ip'), true);
  assert.equal(rl.isBlocked('ip'), true);
});

