using Xunit;
namespace QuantumNetLib.Tests
{
    public class OutcomeHiddenQnl7Tests
    {
        private const long M = 2147483647;

        // A seed whose first Next() is M - 1: the roll where NextFloat() reaches 1f.
        private static long TopRollSeed()
        {
            var inv = (long)System.Numerics.BigInteger.ModPow(48271, M - 2, M);
            return M - inv;
        }

        [Fact]
        public void TopRollSeed_IsTheLargestRoll()
        {
            Assert.Equal((int)(M - 1), new QRandom(TopRollSeed()).Next());
        }

        [Fact]
        public void ArrayOverload_TopRoll_NeverPicksZeroProbabilityItem()
        {
            Assert.Equal("a", new QRandom(TopRollSeed()).Choose(new[] { "a", "b" }, new[] { 1f, 0f }));
            Assert.Equal("b", new QRandom(TopRollSeed()).Choose(new[] { "a", "b", "c" }, new[] { 0.25f, 0.75f, 0f }));
            Assert.Equal("a", new QRandom(TopRollSeed()).GetRandom(new[] { "a", "b" }, new[] { 1f, 0f }));
        }

        [Fact]
        public void VectorOverload_TopRoll_NeverPicksZeroProbabilityItem()
        {
            var list = new Vector<string>();
            list.PushBack("a");
            list.PushBack("b");
            list.PushBack("c");
            var p = new Vector<float>();
            p.PushBack(1f);
            p.PushBack(0f);
            p.PushBack(0f);
            Assert.Equal("a", new QRandom(TopRollSeed()).Choose(list, p));
        }

        [Fact]
        public void OrdinaryRolls_PickTheSameItems()
        {
            var options = new[] { "a", "b", "c" };
            var weights = new[] { 0.2f, 0.3f, 0.5f };
            var r = new QRandom(12345);
            var g = new QRandom(12345);
            for (var n = 0; n < 300; n++)
            {
                var roll = g.NextFloat(0f, 1f);
                var expected = roll < 0.2f ? "a" : roll < 0.5f ? "b" : "c";
                Assert.Equal(expected, r.Choose(options, weights));
            }
        }

        [Fact]
        public void Validation_Unchanged()
        {
            var r = new QRandom(1);
            Assert.Equal(24, Assert.Throws<QException>(() => r.Choose(new[] { "a", "b" }, new[] { 0f, 0f })).ErrorCode);
            Assert.Equal(27, Assert.Throws<QException>(() => r.Choose(new[] { "a", "b" }, new[] { 1f, -1f })).ErrorCode);
            Assert.Equal(23, Assert.Throws<QException>(() => r.Choose(new[] { "a", "b" }, new[] { 1f })).ErrorCode);
            Assert.Equal(22, Assert.Throws<QException>(() => r.Choose(new string[0], new float[0])).ErrorCode);
            var empty = new Vector<float>();
            empty.PushBack(0f);
            var one = new Vector<string>();
            one.PushBack("a");
            Assert.Equal(24, Assert.Throws<QException>(() => r.Choose(one, empty)).ErrorCode);
        }
    }
}

