using Xunit;
namespace QuantumNetLib.Tests
{
    public class OutcomeHiddenQnl8Tests
    {
        [Fact]
        public void UsesOnlyTheGivenCharacters()
        {
            var s = new QRandom(99).GetRandomString(200, "ab");
            Assert.Equal(200, s.Length);
            foreach (var c in s) Assert.True(c == 'a' || c == 'b', "unexpected char " + c);
            Assert.True(s.IndexOf('a') >= 0 && s.IndexOf('b') >= 0, "both characters should appear");
            Assert.Equal("xxxxx", new QRandom(5).GetRandomString(5, "x"));
            const string tr = "\u00e7\u011f\u0131\u015f";
            foreach (var c in new QRandom(3).GetRandomString(50, tr)) Assert.True(tr.IndexOf(c) >= 0);
        }

        [Fact]
        public void ZeroLength_IsEmpty()
        {
            Assert.Equal("", new QRandom(1).GetRandomString(0, "abc"));
        }

        [Fact]
        public void BadInput_ThrowsQException()
        {
            var r = new QRandom(1);
            Assert.Equal(25, Assert.Throws<QException>(() => r.GetRandomString(-1, "abc")).ErrorCode);
            Assert.Throws<QException>(() => r.GetRandomString(5, null));
            Assert.Throws<QException>(() => r.GetRandomString(5, ""));
        }

        [Fact]
        public void ExistingOverload_Unchanged()
        {
            var g = new QRandom(7);
            var chars = new char[10];
            for (var i = 0; i < chars.Length; i++) chars[i] = (char)g.Next(32, 127);
            Assert.Equal(new string(chars), new QRandom(7).GetRandomString(10));
            Assert.Equal(25, Assert.Throws<QException>(() => new QRandom(7).GetRandomString(-1)).ErrorCode);
        }
    }
}

