using Xunit;
namespace QuantumNetLib.Tests
{
    public class OutcomeHiddenQnl10Tests
    {
        [Fact]
        public void IndexOf_FirstMatch_OrMinusOne()
        {
            var v = new Vector<int>();
            v.PushBack(5);
            v.PushBack(7);
            v.PushBack(5);
            Assert.Equal(0, v.IndexOf(5));
            Assert.Equal(1, v.IndexOf(7));
            Assert.Equal(-1, v.IndexOf(9));
            Assert.True(v.Contains(7));
            Assert.False(v.Contains(9));
        }

        [Fact]
        public void UnusedCapacity_IsNotSearched()
        {
            var v = new Vector<int>();
            v.PushBack(5);
            Assert.Equal(-1, v.IndexOf(0));
            Assert.False(v.Contains(0));
            Assert.Equal(-1, new Vector<int>().IndexOf(0));
            Assert.False(new Vector<int>(16).Contains(0));
            v.PushBack(0);
            Assert.Equal(1, v.IndexOf(0));
            v.PopBack();
            Assert.Equal(-1, v.IndexOf(0));
            var big = new Vector<int>();
            for (var i = 1; i <= 6; i++) big.PushBack(i);
            big.Erase(5);
            Assert.Equal(-1, big.IndexOf(6));
            Assert.Equal(-1, big.IndexOf(0));
            big.Clear();
            Assert.False(big.Contains(0));
        }

        [Fact]
        public void Nulls_AndValueEquality()
        {
            var s = new Vector<string>();
            s.PushBack("a");
            s.PushBack(null);
            s.PushBack("b");
            Assert.Equal(1, s.IndexOf(null));
            Assert.Equal(2, s.IndexOf(new string('b', 1)));
            Assert.True(s.Contains(null));
            Assert.Equal(-1, s.IndexOf("c"));
            var one = new Vector<string>();
            one.PushBack("a");
            Assert.Equal(-1, one.IndexOf(null));
            Assert.False(one.Contains(null));
        }
    }
}

